"""Repeated chemistry skills for sections outside the original workbook extension."""
from mcq_authoring import Bank


def chemistry_questions():
    b = Bank()
    N, T = b.numeric, b.text
    for i in range(1, 6):
        n = i + 1
        N('S1.4', f'Find the amount in mol in {18*n} g of water, M = 18 g mol⁻¹.', n, 'Use n = m/M.')
        N('S1.4', f'A solution contains {n/10} mol in 0.500 dm³. Find c in mol dm⁻³.', n/5, 'Use c = n/V with volume in dm³.')
        N('S1.4', f'How many molecules are in {n} mol of CO₂? Use Nₐ = 6.02 × 10²³ mol⁻¹.', n*6.02e23, 'Multiply amount by the Avogadro constant; count molecules, not atoms.')
        N('S1.4', f'Find the mass in g of {n/10} mol of NaCl, M = 58.5 g mol⁻¹.', 5.85*n, 'Use m = nM.')
        N('S1.5', f'An ideal gas occupies {n} dm³ at 100 kPa. At constant temperature, find its volume in dm³ at 200 kPa.', n/2, 'At constant amount and temperature, p₁V₁ = p₂V₂.')
        N('S1.5', f'At constant pressure an ideal gas occupies {n} dm³ at 300 K. Find its volume in dm³ at 450 K.', n*1.5, 'V/T is constant; use absolute temperature.')
        N('S1.5', f'Find the volume in dm³ of {n/10} mol of ideal gas at conditions where Vₘ = 24.0 dm³ mol⁻¹.', 2.4*n, 'Use V = nVₘ at the specified conditions.')
        N('S1.5', f'An ideal gas at 300 K has pressure {n*100} kPa. At fixed volume, find pressure in kPa at 600 K.', n*200, 'At fixed amount and volume, p/T is constant.')
        N('R1.1', f'{n*100} g of water warms by 5.0 K. Use c = 4.18 J g⁻¹ K⁻¹. Find heat absorbed in J.', n*2090, 'Use q = mcΔT; warming water absorbs heat.')
        N('R1.1', f'A reaction involving {n/10} mol releases {n*5} kJ. Find molar ΔH in kJ mol⁻¹.', -50, 'Heat released means negative reaction enthalpy; divide by amount reacted.')
        N('R1.1', f'A {n*10} g sample absorbs {n*120} J and warms by 4 K. Find c in J g⁻¹ K⁻¹.', 3, 'Rearrange q = mcΔT to c = q/(mΔT).')
        N('R1.1', f'A calorimeter has heat capacity {n*100} J K⁻¹. A reaction raises its temperature by 3 K. Assuming no loss, find reaction heat in J.', -n*300, 'The reaction loses the heat gained by the calorimeter: qᵣ = −CΔT.')
        N('R1.2', f'A → B has ΔH = −{n*20} kJ mol⁻¹ and B → C has ΔH = +10 kJ mol⁻¹. Find ΔH for A → C.', -n*20+10, 'Add enthalpy changes along the route, using Hess’s law.')
        N('R1.2', f'A → B has ΔH = −{n*30} kJ mol⁻¹. Find ΔH in kJ mol⁻¹ for B → A.', n*30, 'Reversing a reaction reverses the sign of its enthalpy change.')
        N('R1.2', f'For a reaction, total bond energy of bonds broken is {n*200+100} kJ mol⁻¹ and of bonds formed is {n*200+250} kJ mol⁻¹. Estimate ΔH.', -150, 'ΔH ≈ sum of bond energies broken minus sum formed.')
        N('R1.2', f'For A + B → C, ΔHf° values are A: −{n*10}, B: −20 and C: −{n*10+100} kJ mol⁻¹. Find ΔH°.', -80, 'Use formation enthalpies of products minus those of reactants, including coefficients.')
        N('R1.3', f'A fuel releases 40 kJ g⁻¹. Find energy in kJ from complete combustion of {n*5} g.', n*200, 'Multiply specific energy by mass burned.')
        N('R1.3', f'A heater receives {n*100} kJ of fuel energy and delivers {n*70} kJ usefully. Find efficiency as a percentage.', 70, 'Efficiency = useful output/input × 100%.')
        N('R1.3', f'Complete combustion of {n} mol of propane C₃H₈ produces how many mol of CO₂?', 3*n, 'Each mole of propane has three moles of carbon atoms, producing three moles of CO₂.')
        N('R1.3', f'A fuel has molar combustion enthalpy −{n*100} kJ mol⁻¹ and molar mass {n*10} g mol⁻¹. Find specific energy in kJ g⁻¹.', 10, 'Divide the magnitude of molar combustion enthalpy by molar mass.')
        N('R1.4', f'AHL: ΔH = −{n*10} kJ mol⁻¹ and ΔS = −20 J K⁻¹ mol⁻¹. Find ΔG in kJ mol⁻¹ at 300 K.', -n*10+6, 'Use ΔG = ΔH − TΔS; first convert entropy to −0.020 kJ K⁻¹ mol⁻¹.')
        N('R1.4', f'AHL: ΔH = {n*10} kJ mol⁻¹ and ΔS = 50 J K⁻¹ mol⁻¹. At what temperature in K is ΔG = 0, assuming both are constant?', n*200, 'Set T = ΔH/ΔS and use consistent joule units.')
        T('R1.4', f'AHL: A process at {250+50*i} K has ΔH < 0 and ΔS > 0. Which conclusion follows?', 'It is thermodynamically spontaneous at this temperature.', ['It must be fast.', 'It has positive ΔG.', 'It requires a catalyst to make ΔG negative.'], 'Both ΔH and −TΔS are negative at positive temperature; spontaneity does not specify rate.')
        N('R1.4', f'AHL: For A → 2B, S°(A) = {n*20} and S°(B) = {n*15} J K⁻¹ mol⁻¹. Find reaction ΔS° in these units.', n*10, 'Sum stoichiometrically weighted entropies of products minus reactants.')
        N('R2.1', f'For N₂ + 3H₂ → 2NH₃, {n} mol of N₂ reacts with excess H₂. Find mol of NH₃ formed.', 2*n, 'The mole ratio NH₃:N₂ is 2:1.')
        N('R2.1', f'For 2Mg + O₂ → 2MgO, {n} mol of Mg reacts with {n} mol of O₂. Find mol of MgO formed.', n, 'Mg is limiting; the Mg:MgO ratio is 1:1.')
        N('R2.1', f'Theoretical product mass is {n*10} g and actual mass is {n*8} g. Find percentage yield.', 80, 'Percentage yield = actual/theoretical × 100%.')
        N('R2.1', f'{n*10} cm³ of 0.100 mol dm⁻³ HCl neutralizes {n*5} cm³ NaOH. Find NaOH concentration in mol dm⁻³.', .2, 'The reaction is 1:1; c(acid)V(acid) = c(base)V(base).')
        N('R2.2', f'{n*12} cm³ of gas forms in 6 s. Find average formation rate in cm³ s⁻¹.', n*2, 'Average rate is change in volume divided by elapsed time.')
        N('R2.2', f'Reactant concentration falls from {n/10+.1:.2f} to 0.10 mol dm⁻³ in 20 s. Find its positive average disappearance rate in mol dm⁻³ s⁻¹.', n/200, 'Take the concentration decrease divided by time.')
        T('R2.2', f'A reaction is run at {20+5*i} °C and then 10 °C hotter. Why is the hotter reaction usually faster?', 'A larger fraction of collisions has energy at least equal to the activation energy.', ['The activation energy necessarily decreases.', 'The equilibrium constant always increases.', 'Every collision now forms products.'], 'Heating changes the energy distribution; it does not itself lower the activation barrier.')
        T('R2.2', f'A catalyst is added to a reaction initially at {250+10*i} K. What does it provide?', 'An alternative mechanism with a lower activation barrier.', ['A more negative reaction enthalpy.', 'A larger equilibrium yield in every reaction.', 'Energy that is consumed permanently.'], 'A catalyst accelerates approach to equilibrium through an alternative pathway and is regenerated.')
        N('R2.3', f'For A ⇌ B at equilibrium, [A] = 0.20 and [B] = {n/10:.1f} mol dm⁻³. Find Kc.', n/2, 'Kc = [B]/[A] for this 1:1 reaction.')
        N('R2.3', f'For A ⇌ 2B, equilibrium [A] = {n/10:.1f} and [B] = 0.20 mol dm⁻³. Find Kc numerically.', .04/(n/10), 'Kc = [B]²/[A]; coefficients become exponents.')
        T('R2.3', f'N₂(g) + 3H₂(g) ⇌ 2NH₃(g) is at {n*100} kPa. Compression at constant temperature shifts equilibrium which way?', 'Toward NH₃.', ['Toward N₂ and H₂.', 'No shift because K changes.', 'All reactants are consumed.'], 'Compression favors the side with fewer gas particles: two on the product side versus four on the reactant side.')
        T('R2.3', f'An exothermic forward reaction is at equilibrium at {300+20*i} K. What happens to K on heating?', 'K decreases.', ['K increases.', 'K becomes zero.', 'K is unchanged for every temperature.'], 'Heating favors the endothermic reverse direction, reducing the equilibrium product-to-reactant ratio.')
        N('R3.1', f'Find pH when [H⁺] = 1.0 × 10⁻{n} mol dm⁻³.', n, 'pH = −log₁₀[H⁺].')
        N('R3.1', f'At 25 °C a solution has pH {n}. Find pOH.', 14-n, 'At 25 °C, pH + pOH = 14.00.')
        N('R3.1', f'{n*10} cm³ of 0.100 mol dm⁻³ monoprotic strong acid is diluted to {n*100} cm³. Find its ideal pH.', 2, 'Dilution lowers concentration tenfold to 0.0100 mol dm⁻³; full dissociation gives pH 2.')
        T('R3.1', f'In NH₃ + H₂O ⇌ NH₄⁺ + OH⁻ at {20+i} °C, which species is the conjugate acid of NH₃?', 'NH₄⁺', ['OH⁻', 'H₂O', 'H₃O⁺'], 'A conjugate acid differs from its base by one added proton.')
        N('R3.2', f'How many mol of electrons are released when {n} mol of Mg forms Mg²⁺?', 2*n, 'Mg → Mg²⁺ + 2e⁻; each mole of Mg releases two moles of electrons.')
        N('R3.2', f'How many mol of electrons are needed to reduce {n} mol of Al³⁺ to Al?', 3*n, 'Al³⁺ + 3e⁻ → Al.')
        T('R3.2', f'In a cell containing {n/10} mol dm⁻³ Zn²⁺, zinc undergoes Zn → Zn²⁺ + 2e⁻. What is this electrode?', 'The anode, where oxidation occurs.', ['The cathode, where oxidation occurs.', 'The anode, where reduction occurs.', 'The cathode, where reduction occurs.'], 'Oxidation is loss of electrons and always occurs at the anode.')
        N('R3.2', f'AHL: A cell has E°(cathode) = +{n/10:.1f} V and E°(anode) = −0.40 V, both reduction potentials. Find E°cell in V.', n/10+.4, 'Subtract anode reduction potential from cathode reduction potential.')
    # Concept banks use five chemical contexts, with four complementary questions each.
    for metal, electrons in [('Na',1),('Mg',2),('Al',3),('K',1),('Ca',2)]:
        T('S2.3', f'What attracts the particles together in solid {metal}?', 'Electrostatic attraction between positive metal ions and delocalized electrons.', ['Attraction between neutral molecules.', 'Hydrogen bonds between atoms.', 'Localized electron pairs between discrete molecules.'], 'The metallic model has positive ion cores surrounded by mobile delocalized electrons.')
        T('S2.3', f'Why can solid {metal} conduct electricity?', 'Delocalized electrons can move through the structure.', ['Positive ions flow through the solid.', 'Protons leave the nuclei.', 'It contains moving anions.'], 'Mobile electrons carry charge through a solid metal; the ion cores remain in the lattice.')
        T('S2.3', f'Why can pure {metal} be shaped without its bonding immediately collapsing?', 'Layers can slide while attraction to delocalized electrons persists.', ['Each atom is bonded to only one neighbor.', 'The metal consists of soft molecules.', 'All electrons are localized in fixed pairs.'], 'Metallic attraction is non-directional, so sliding layers can remain bonded.')
        N('S2.3', f'In a simple metallic model, each {metal} atom contributes {electrons} outer electron(s). How many delocalized electrons come from 10 atoms?', 10*electrons, 'Multiply the number of atoms by the specified contribution per atom.')
    materials = [('brass','an alloy of copper and zinc'),('bronze','an alloy of copper and tin'),('steel','an alloy based on iron with carbon')]
    for name, desc in materials:
        T('S2.4', f'{name.capitalize()} is {desc}. Which description fits an alloy?', 'A metallic material containing more than one element.', ['A substance containing only identical molecules.', 'A salt made only of non-metals.', 'A pure element with no other atoms.'], 'Alloys combine a metal with other elements while retaining metallic properties.')
        T('S2.4', f'Why can adding differently sized atoms make {name} harder than its main pure metal?', 'They disrupt regular layers and hinder sliding.', ['They eliminate every electron.', 'They turn all bonds into hydrogen bonds.', 'They ensure layers slide more easily.'], 'Distorted layers make movement of dislocations more difficult; properties depend on alloy composition.')
        T('S2.4', f'A sample of {name} conducts electricity. Which particles principally carry the current?', 'Delocalized electrons.', ['Neutrons.', 'Nuclei moving between electrodes.', 'Neutral molecules only.'], 'An alloy retains metallic bonding and mobile electrons.')
        T('S2.4', f'A manufacturer changes the composition of {name}. Why test the resulting material?', 'Changing composition can change strength, corrosion resistance and other properties.', ['All alloys have identical properties.', 'Composition determines only color.', 'Adding any element always doubles strength.'], 'Material design balances properties; composition alone does not guarantee a universal improvement.')
    for monomer, polymer, unit in [('ethene', 'poly(ethene)', '–CH₂–CH₂–'), ('propene', 'poly(propene)', '–CH₂–CH(CH₃)–')]:
        T('S2.4', f'What happens to the carbon–carbon double bond when {monomer} forms {polymer} by addition polymerization?', 'The double bond becomes a single bond as new links join monomers.', ['All carbon atoms are removed.', 'Every carbon–carbon bond becomes a triple bond.', 'The monomer remains a separate molecule.'], 'The alkene π bond is replaced by bonds connecting monomers into a chain; the carbon skeleton is retained.')
        T('S2.4', f'Which is the repeat unit of {polymer}, made from {monomer}?', unit, ['–O–O–', '–C≡C–', '–CO–NH–'], 'Open the alkene double bond and retain its attached groups to obtain the addition-polymer repeat unit.')
        T('S2.4', f'Which small-molecule by-product must be released when pure {monomer} forms {polymer} by addition polymerization?', 'None.', ['Water.', 'Hydrogen chloride.', 'Carbon dioxide.'], 'Addition polymerization incorporates monomers without eliminating a small molecule.')
        T('S2.4', f'Why can chain length affect the properties of {polymer}?', 'Longer chains can have more intermolecular contacts and entanglements.', ['Longer chains must contain only ionic bonds.', 'Longer chains have no intermolecular forces.', 'Chain length changes carbon into a different element.'], 'Polymer behavior depends on chain length, branching and organization, which affect interactions between chains.')
    for symbol,z,period,group in [('Li',3,2,1),('Na',11,3,1),('Mg',12,3,2),('Al',13,3,13),('Cl',17,3,17)]:
        N('S3.1', f'A neutral {symbol} atom has atomic number {z}. How many electrons does it contain?', z, 'A neutral atom has equal numbers of protons and electrons; atomic number counts protons.')
        N('S3.1', f'{symbol} is in period {period}. How many electron shells are occupied in its ground-state atom?', period, 'For these main-group atoms, the period gives the number of occupied shells.')
        N('S3.1', f'{symbol} is in group {group}. How many outer-shell electrons does a neutral atom have?', group if group<3 else group-10, 'For groups 1–2 use the group number; for groups 13–18 subtract 10.')
        T('S3.1', f'Across period {period}, why does atomic radius generally decrease toward {symbol} and then the right?', 'Nuclear charge increases while electrons enter the same main shell.', ['An entire new shell is added at each step.', 'Nuclear charge decreases.', 'All outer electrons disappear.'], 'Greater effective nuclear attraction generally pulls the same main shell closer; the statement is an overall trend.')
    for formula,family,group in [('CH₃OH','alcohol','hydroxyl'),('CH₃CHO','aldehyde','terminal carbonyl'),('CH₃COCH₃','ketone','carbonyl between two carbon groups'),('CH₃COOH','carboxylic acid','carboxyl'),('CH₃COOCH₃','ester','ester linkage')]:
        T('S3.2', f'Which family contains {formula}?', family, [x for x in ['alcohol','aldehyde','ketone','carboxylic acid','ester'] if x!=family][:3], f'The structure contains a {group} group, characteristic of a {family}.')
        T('S3.2', f'Which group identifies {formula}?', group, [x for x in ['hydroxyl','terminal carbonyl','carboxyl','ester linkage'] if x!=group][:3], f'The condensed formula shows the {group} group.')
        T('S3.2', f'A homologous series containing {formula} has successive members differing by what?', 'CH₂', ['H₂O', 'CO₂', 'O₂'], 'Successive members of a homologous series differ by CH₂ and share a functional group.')
        T('S3.2', f'How would a structural isomer of {formula} compare with it?', 'Same molecular formula, different atom connectivity.', ['Different molecular formula, same connectivity.', 'Same connectivity and same formula only.', 'Always the same physical properties.'], 'Structural isomerism concerns different bonding arrangements for the same numbers of each kind of atom.')
    for alkane,radical in [('CH₄','CH₃•'),('C₂H₆','C₂H₅•'),('C₃H₈','C₃H₇•'),('C₄H₁₀','C₄H₉•'),('C₅H₁₂','C₅H₁₁•')]:
        T('R3.3', f'In photochemical chlorination of {alkane}, what does Cl₂ → 2Cl• represent?', 'Initiation by homolytic bond fission.', ['Termination by heterolytic fission.', 'Propagation with no radicals.', 'Acid–base neutralization.'], 'Light initiates the chain by splitting the bond equally, giving each chlorine one electron.')
        T('R3.3', f'In chlorination of {alkane}, Cl• removes H to give HCl and {radical}. Which stage is this?', 'Propagation.', ['Initiation.', 'Termination.', 'Precipitation.'], 'One radical is consumed and another is formed, continuing the chain.')
        T('R3.3', f'Two {radical} radicals join by forming a covalent bond. Which stage is this?', 'Termination.', ['Propagation.', 'Initiation.', 'Heterolytic cleavage.'], 'Combining radicals removes radical carriers without generating a new one.')
        T('R3.3', f'What defines the species {radical} as a radical?', 'It contains an unpaired electron.', ['It must carry a positive charge.', 'It must contain oxygen.', 'It has no electrons.'], 'The dot represents an unpaired electron; radicals need not be charged.')
    for donor in ['NH₃','H₂O','OH⁻','Cl⁻','CN⁻']:
        T('R3.4', f'When {donor} donates a lone pair to form a bond, it acts as what?', 'A Lewis base.', ['A Lewis acid.', 'An electron-pair acceptor.', 'A proton donor in every reaction.'], 'Lewis bases donate electron pairs; this definition does not require proton transfer.')
        T('R3.4', f'A curved arrow shows bond formation by {donor} donating a lone pair. Where should the arrow start?', 'At the donated lone pair.', ['At the positive charge on the acceptor.', 'At a nucleus.', 'At an empty orbital on the acceptor.'], 'A full curved arrow represents movement of a pair of electrons, from its source to its destination.')
        T('R3.4', f'{donor} attacks an electron-deficient carbon using an electron pair. What is its role?', 'Nucleophile.', ['Electrophile.', 'Free radical solely because it reacts.', 'Inert spectator in every reaction.'], 'A nucleophile donates an electron pair to an electrophilic site.')
        N('R3.4', f'{donor} forms one coordinate bond by donating one lone pair. How many electrons does the donor supply to this bond initially?', 2, 'Both bonding electrons initially come from the donor; after formation it is a covalent bond.')
    return b.finish(['S1.4','S1.5','S2.3','S2.4','S3.1','S3.2','R1.1','R1.2','R1.3','R1.4','R2.1','R2.2','R2.3','R3.1','R3.2','R3.3','R3.4'])
